from itertools import product
from math import gcd
from typing import Sequence

def qvalue(a: Sequence[Sequence[int]], v: Sequence[int]) -> int:
    return sum(a[i][j]*v[i]*v[j] for i in range(len(v)) for j in range(len(v)))

def primitive(v: Sequence[int]) -> bool:
    g = 0
    for x in v: g = gcd(g, abs(x))
    return g == 1

def search(a: Sequence[Sequence[int]], bound: int) -> list[tuple[int, ...]]:
    n = len(a); out: list[tuple[int, ...]] = []
    for v in product(range(-bound, bound + 1), repeat=n):
        if not any(v) or not primitive(v): continue
        if next(x for x in v if x) < 0: continue
        if qvalue(a, v) == 0: out.append(v)
    return out

if __name__ == "__main__":
    A = [[1,0,0],[0,1,0],[0,0,-1]]
    hits = search(A, 5)
    assert (3,4,5) in hits
    print(hits)

from fractions import Fraction
from typing import Sequence, TypeVar
T = TypeVar("T", int, Fraction, complex)

def qvalue(a: Sequence[Sequence[T]], v: Sequence[T]) -> T:
    return sum(a[i][j]*v[i]*v[j] for i in range(len(v)) for j in range(len(v)))

def extend(v: Sequence[Fraction]) -> list[complex]:
    return [complex(x) for x in v]

if __name__ == "__main__":
    A = [[1,0,0],[0,1,0],[0,0,-1]]
    v = [Fraction(3), Fraction(4), Fraction(5)]
    w = extend(v)
    assert qvalue(A, v) == 0 and qvalue(A, w) == 0
    print("base witness:", v, "extended witness:", w)

from typing import Sequence
Matrix = Sequence[Sequence[int]]

def transpose(a: Matrix) -> list[list[int]]:
    return [list(row) for row in zip(*a)]

def multiply(a: Matrix, b: Matrix) -> list[list[int]]:
    return [[sum(a[i][k]*b[k][j] for k in range(len(b)))
             for j in range(len(b[0]))] for i in range(len(a))]

def matvec(a: Matrix, v: Sequence[int]) -> list[int]:
    return [sum(x*y for x,y in zip(row,v)) for row in a]

def qvalue(a: Matrix, v: Sequence[int]) -> int:
    av = matvec(a,v); return sum(x*y for x,y in zip(v,av))

if __name__ == "__main__":
    A = [[1,0,0],[0,1,0],[0,0,-1]]
    P = [[1,1,0],[0,1,0],[0,0,1]]
    transformed = multiply(transpose(P), multiply(A,P))
    u = [-1,4,5]
    assert qvalue(transformed,u) == qvalue(A,matvec(P,u)) == 0
    print("transformed matrix:", transformed, "zero:", u)

